function plot_integrated_missions(root)
% Actual integrated fleet/object recordings, without synthetic cost envelopes.
if nargin<1,root=fileparts(fileparts(mfilename('fullpath')));end
d=jsondecode(fileread(fullfile(root,'research','integrated','figure_data.json')));out=fullfile(root,'assets','result');set(groot,'defaultFigureVisible','off');set(groot,'defaultAxesFontSize',10);colors=[.07 .42 .59;.75 .32 .13;.47 .31 .65;.37 .48 .56];names={'Fixed cyclic','Nearest-k','Cyclic repair','Geometric repair'};
f=figure('Color','w','Position',[20 20 1640 1220]);tiledlayout(3,2,'Padding','compact','TileSpacing','compact');
nexttile;stages=zeros(4,3);for i=1:4,s=d.primary(i).summary;stages(i,:)=[s.grantTime,s.placementTime-s.grantTime,s.confirmationTime-s.placementTime];end;b=barh(1:4,stages,'stacked');phaseColors=[.30 .60 .77;.88 .55 .31;.58 .43 .72];for i=1:3,b(i).FaceColor=phaseColors(i,:);end;yticks(1:4);yticklabels(names);set(gca,'YDir','reverse');grid on;xlabel('Actual physical time (s)');title('Causal workflow stages; clock starts with evidence');legend({'Inspect / obtain grant','Carry / support / notify','External confirmation'},'Location','southeast');
keys={'background','busy','height','bytes','H'};titles={'Background inspection is a separate objective','Resource duration follows actual physical state','Actual free-object height in the shared world','One routed ledger includes lifecycle and evidence','Common full-map nearest-k distance cost'};yl={'Weighted background completed (%)','Accumulated carrier occupation (s)','Tray height (m)','Cumulative byte-hops / 10^6','H (m^2)'};
for h=1:5,nexttile;hold on;for i=1:4,p=d.primary(i);v=p.(keys{h});if h==1,v=100*v;elseif h==4,v=v/1e6;end;plot(p.time,v,'Color',colors(i,:),'LineWidth',1.6);end;grid on;xlabel('Physical time (s)');ylabel(yl{h});title(titles{h});if h==1,ylim([0 105]);legend(names,'Location','southeast');end;end
sgtitle({'ONE MuJoCo fleet/object world: N=6, k=2, seed2718; all policies use the SAME viewpoint executor','Pre-grasp fixture, actual dual-arm transport, physical support, external confirmation; no hardware claim'},'FontWeight','bold');exportgraphics(f,fullfile(out,'W01_integrated_workflows.png'),'Resolution',150);close(f);
f=figure('Color','w','Position',[20 20 1700 1280]);tiledlayout(3,2,'Padding','compact','TileSpacing','compact');r=d.removal(3);g=d.grasp(3);p=d.primary(3);
nexttile;yyaxis left;plot(r.time,r.height,'LineWidth',1.6);ylabel('Actual tray height (m)');yyaxis right;stairs(r.time,r.N,'LineWidth',1.5);ylim([5 8]);ylabel('Active physical robot count N');xline(12,'k--');grid on;xlabel('Physical time (s)');title('Observer removal preserves tray and survivor states');
nexttile;stairs(r.time,[r.N r.gcd r.available],'LineWidth',1.6);xline(12,'k--');grid on;xlabel('Physical time (s)');ylabel('Different integer counts');title('Occupation changes availability; removal changes N and gcd');legend({'N','gcd(N,k)','Available inspection robots'},'Location','east');
nexttile;plot(g.time,[g.left g.right],'LineWidth',1.6);xline(g.summary.grantTime+6,'k--');grid on;xlabel('Physical time (s)');ylabel('Actual hand force on tray (N)');title('Right constraint fails: no replacement grasp is invented');legend({'Left F_z','Right F_z','Physical fault'},'Location','best');
nexttile;plot(p.time,p.objectError,'Color',colors(3,:),'LineWidth',1.6);hold on;plot(g.time,g.objectError,'Color',[.72 .22 .18],'LineWidth',1.6);xline(g.summary.grantTime+6,'k--');grid on;xlabel('Physical time (s)');ylabel('Actual placement error (m)');title('Failed payload stays quarantined; background work can finish');legend({'Normal cyclic repair','Grasp fault cyclic repair'},'Location','northeast');
nexttile;imagesc(1:10,1:4,d.success');colormap(gca,[.94 .76 .70;.73 .89 .78]);clim([0 1]);for i=1:10,for j=1:4,if d.success(i,j),s='Y';else,s='N';end;text(i,j,sprintf('%s / %.0f',s,100*d.background(i,j)),'HorizontalAlignment','center','FontSize',9);end;end;yticks(1:4);yticklabels(names);xticks(1:10);xticklabels({'seed2718','seed42','seed19','N5 k2','N6 k3','N7 -> 6','grasp loss','18k budget','disconnected','external quorum'});xtickangle(35);title('Each cell: pipeline Y/N / background percent; all 40 trials');
nexttile;b=bar(d.confirmation,'grouped');for i=1:4,b(i).FaceColor=colors(i,:);end;grid on;ylabel('Actual confirmation time (s)');xticks(1:6);xticklabels({'seed2718','seed42','seed19','N5 k2','N6 k3','N7 -> 6'});xtickangle(25);title('Policy ranking changes with geometry, capacity and failure');legend(names,'Location','northwest');
sgtitle({'Faults and arithmetic interpretation in the SAME task loop','Reliable sampled certificates and explicit reservations; no universal scheduling or whole-body convergence guarantee'},'FontWeight','bold');exportgraphics(f,fullfile(out,'W02_integrated_faults.png'),'Resolution',150);close(f);
end
